<?php
namespace App\Http\Controllers\Admin; use App\Http\Controllers\Controller; use App\Models\Faq; use Illuminate\Http\Request; use Inertia\Inertia;
class FaqController extends Controller { public function index(){return Inertia::render('Admin/Faqs',['items'=>Faq::orderBy('sort_order')->latest()->get()]);} public function store(Request $request){Faq::create($this->data($request));return back();} public function update(Request $request,Faq $faq){$faq->update($this->data($request));return back();} public function destroy(Faq $faq){$faq->delete();return back();} private function data(Request $request):array{return $request->validate(['question'=>['required','string','max:500'],'answer'=>['required','string','max:3000'],'sort_order'=>['nullable','integer','min:0'],'is_active'=>['boolean']]);} }
